package com.cpq.currency.resource;
import com.cpq.common.dto.ApiResponse; import com.cpq.common.security.RoleAllowed; import com.cpq.common.security.SessionHelper; import com.cpq.currency.dto.*; import com.cpq.currency.service.ExchangeRateService; import io.vertx.core.http.HttpServerRequest; import jakarta.inject.Inject; import jakarta.ws.rs.*; import jakarta.ws.rs.core.*; import org.jboss.resteasy.reactive.RestForm; import org.jboss.resteasy.reactive.multipart.FileUpload; import org.apache.poi.ss.usermodel.*; import java.io.InputStream; import java.nio.file.Files; import java.time.LocalDate; import java.util.*;
@Path("/api/cpq/currencies") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) @RoleAllowed({"SALES_MANAGER","PRICING_MANAGER","SYSTEM_ADMIN"})
public class CurrencyResource {
 @Inject ExchangeRateService service; @Inject SessionHelper session; @Context HttpServerRequest request;
 @GET public ApiResponse<List<CurrencyDTO>> list(@QueryParam("enabled") Boolean enabled){List<CurrencyDTO> rows=service.currencies();if(Boolean.TRUE.equals(enabled))rows=rows.stream().filter(x->x.enabled).toList();return ApiResponse.success(rows);}
 @POST public ApiResponse<CurrencyDTO> create(CurrencyRequest r){return ApiResponse.success(service.create(r));}
 @PUT @Path("/{code}") public ApiResponse<CurrencyDTO> update(@PathParam("code")String c,CurrencyRequest r){return ApiResponse.success(service.update(c,r));}
 @DELETE @Path("/{code}") public ApiResponse<Void> delete(@PathParam("code")String c){service.delete(c);return ApiResponse.success();}
 @GET @Path("/{code}/rates") public ApiResponse<Map<String,Object>> rates(@PathParam("code")String c,@QueryParam("fromDate")String f,@QueryParam("toDate")String t){LocalDate from=parse(f),to=parse(t);return ApiResponse.success(Map.of("currency",c,"items",service.rates(c,from,to)));}
 @POST @Path("/{code}/rates") public ApiResponse<CurrencyRateDTO> add(@PathParam("code")String c,RateRequest r){return ApiResponse.success(service.addRate(c,r,session.getCurrentUserIdOrFallback(request)));}
 @POST @Path("/{code}/rates/import") @Consumes(MediaType.MULTIPART_FORM_DATA) public ApiResponse<Map<String,Object>> importRates(@PathParam("code")String c,@RestForm("file") FileUpload file){if(file==null)throw new BadRequestException("file 不能为空");List<RateRequest> rows=new ArrayList<>();try(InputStream in=Files.newInputStream(file.uploadedFile());Workbook wb=WorkbookFactory.create(in)){Sheet s=wb.getSheetAt(0);for(int i=1;i<=s.getLastRowNum();i++){Row row=s.getRow(i);if(row==null)continue;String date=text(row.getCell(0));String rate=text(row.getCell(1));String source=text(row.getCell(2));if(date.isBlank()&&rate.isBlank())continue;RateRequest r=new RateRequest();r.effectiveDate=LocalDate.parse(date);r.rate=new java.math.BigDecimal(rate);r.source=source;rows.add(r);}}catch(Exception e){throw new BadRequestException("汇率文件格式无效: "+e.getMessage());}int n=service.importRates(c,rows,session.getCurrentUserIdOrFallback(request));return ApiResponse.success(Map.of("createdCount",n,"failedCount",0));}
 private String text(Cell c){if(c==null)return "";if(c.getCellType()==CellType.NUMERIC&&DateUtil.isCellDateFormatted(c))return c.getLocalDateTimeCellValue().toLocalDate().toString();if(c.getCellType()==CellType.NUMERIC)return new java.math.BigDecimal(c.getNumericCellValue()).toPlainString();return c.toString().trim();}
 private LocalDate parse(String x){return x==null||x.isBlank()?null:LocalDate.parse(x);}
}
